  `type` varchar(50) DEFAULT NULL COMMENT '类型',
  `post_id` int DEFAULT NULL COMMENT '商品id',
  `order_num` varchar(50) DEFAULT NULL COMMENT '订单号',
  `create_time` datetime DEFAULT '0000-00-00 00:00:00' COMMENT '创建时间',
  `modified_time` datetime DEFAULT '0000-00-00 00:00:00' COMMENT '更新时间',
  `status` varchar(50) DEFAULT NULL COMMENT '状态',
  `meta` longtext COMMENT '元数据',
  `other` longtext COMMENT '其它',
  PRIMARY KEY (`id`),
  KEY `card` (`card`),
  KEY `password` (`password`),
  KEY `type` (`type`),
  KEY `status` (`status`),
  KEY `create_time` (`create_time`,`modified_time`,`id`),
  KEY `post_id` (`post_id`,`order_num`,`id`)
